'use strict';
// Keep scene assets visible in project time, including scenes that are not selected.
function useTimelineScene(s,at=0){sceneIndex=project.scenes.indexOf(s);time=clamp(at,0,s.duration);selectedAudio=null;selectLayers([])}
const renderBeforeContinuousTimeline=renderTimeline;renderTimeline=function(){
 renderBeforeContinuousTimeline();const active=current(),body=$('timelineBody'),scroll=body.scrollTop;
 for(const el of document.querySelectorAll('.timeline-clip[data-object-id],.timeline-clip.caption'))el.dataset.ownerSceneId=active.id;
 let offset=0;for(const s of project.scenes){const sceneAt=offset;offset+=s.duration;if(s===active)continue;
  for(const o of s.objects.slice().reverse()){
   const row=lane(s.name+' · '+o.name),clip=makeClip(row.area,{start:sceneAt+clipStart(o),end:sceneAt+clipEnd(o,s),label:o.name,kind:o.type,locked:o.locked,onselect:()=>{useTimelineScene(s,clipStart(o));selectLayers([o.id])},onmove:change=>{useTimelineScene(s,clipStart(o));selectLayers([o.id]);moveVisual(o,change)}});clip.dataset.objectId=o.id;clip.dataset.ownerSceneId=s.id;
   const lock=document.createElement('button');lock.textContent=o.locked?'🔒':'Lock';lock.title=o.locked?'Unlock layer editing':'Lock layer editing';lock.onclick=()=>{o.locked=!o.locked;save();render()};row.title.append(lock);
   for(const k of o.keys){if(k.t<clipStart(o)||k.t>clipEnd(o,s))continue;const diamond=document.createElement('span');diamond.className='clip-diamond';diamond.style.left=(k.t-clipStart(o))*timelineZoom+'px';clip.append(diamond)}
  }
  if(s.captions?.length){const row=lane(s.name+' · Captions');s.captions.forEach((c,index)=>{const el=makeClip(row.area,{start:sceneAt+c.start,end:sceneAt+c.end,label:c.text,kind:'caption',onselect:()=>useTimelineScene(s,c.start),onmove:({delta,mode})=>{useTimelineScene(s,c.start);if(mode==='left')c.start=clamp(c.start+delta,0,c.end-.1);else if(mode==='right')c.end=clamp(c.end+delta,c.start+.1,s.duration);else{delta=clamp(delta,-c.start,s.duration-c.end);c.start+=delta;c.end+=delta}}});el.dataset.ownerSceneId=s.id;el.dataset.captionIndex=index})}
 }
 let caption=0;document.querySelectorAll('.timeline-clip.caption').forEach(el=>{if(el.dataset.captionIndex===undefined)el.dataset.captionIndex=caption++});
 const sceneClips=document.querySelectorAll('.timeline-clip.scene');sceneClips.forEach((el,index)=>{if(index>=project.scenes.length-1)return;const b=document.createElement('button');b.className='scene-transition-point';b.textContent=project.scenes[index].transition==='cut'?'＋':'◇';b.title='Transition: '+project.scenes[index].name+' → '+project.scenes[index+1].name;b.setAttribute('aria-label',b.title);b.onpointerdown=e=>{e.stopPropagation();e.preventDefault()};b.onclick=e=>{e.stopPropagation();openSceneTransitionAt(index)};el.append(b)});body.scrollTop=scroll;
};
const sceneTransitionStyle=document.createElement('style');sceneTransitionStyle.textContent='@media(min-height:680px){main{grid-template-rows:minmax(240px,1fr) 350px}}.scene-transition-point{position:absolute;right:0;top:0;height:100%;z-index:7;padding:0 6px!important;background:#55436f!important;border:1px solid #d5b5ff!important}.timeline-clip.scene{overflow:visible}.scene-transition-point:hover{background:#9166bd!important}#sceneBoundaryDialog{width:500px}';document.head.append(sceneTransitionStyle);
document.body.insertAdjacentHTML('beforeend','<dialog id="sceneBoundaryDialog"><div class="tool-heading"><h2>Scene transition</h2><button id="closeSceneBoundary">Close</button></div><p id="sceneBoundaryNames" class="note"></p><label>Transition<select id="sceneBoundaryType"></select></label><label>Duration (seconds)<input id="sceneBoundaryDuration" type="number" min="0.1" max="3" step="0.1" value="0.5"></label><p class="note">Blends the whole scene, including its background, into the next scene. Crossfade gives a smooth join; Cut keeps a continuous matching background.</p><button id="applySceneBoundary" class="primary">Apply transition</button><button id="previewSceneBoundary">Play transition</button></dialog>');
for(const [value,name]of [['cut','Cut / continuous background'],['crossfade','Crossfade'],['slide-left','Slide left'],['slide-right','Slide right'],['zoom','Zoom'],['match','Match characters and objects']]){const o=document.createElement('option');o.value=value;o.textContent=name;$('sceneBoundaryType').append(o)}
let sceneBoundaryId=null;function openSceneTransitionAt(index){stop();const s=project.scenes[index],next=project.scenes[index+1];if(!s||!next)return toast('Add a next scene to create a transition.');sceneBoundaryId=s.id;$('sceneBoundaryNames').textContent=s.name+' → '+next.name;$('sceneBoundaryType').value=s.transition||'cut';$('sceneBoundaryDuration').value=s.transitionDuration||.5;$('sceneBoundaryDialog').showModal()}
function applySceneBoundary(){const s=project.scenes.find(s=>s.id===sceneBoundaryId);if(!s||project.scenes.indexOf(s)===project.scenes.length-1)throw Error('Choose two neighboring scenes.');s.transition=$('sceneBoundaryType').value;s.transitionDuration=clamp(+$('sceneBoundaryDuration').value||.5,.1,Math.min(3,s.duration));save();render();return s}
$('applySceneBoundary').onclick=()=>{try{applySceneBoundary();$('sceneBoundaryDialog').close();toast('Scene transition applied.')}catch(e){toast(e.message)}};$('closeSceneBoundary').onclick=()=>$('sceneBoundaryDialog').close();$('previewSceneBoundary').onclick=()=>{const s=applySceneBoundary(),offset=project.scenes.slice(0,project.scenes.indexOf(s)).reduce((n,s)=>n+s.duration,0);$('sceneBoundaryDialog').close();seekGlobal(offset+s.duration-s.transitionDuration);play()};
document.querySelector('.timeline-top').append(Object.assign(document.createElement('button'),{id:'timelineSceneTransition',textContent:'Scene transition',onclick:()=>openSceneTransitionAt(sceneIndex)}));
// A direct character composer reuses the tested voice/dialogue pipeline.
async function openCharacterComposer(o=object()){
 if(!isAnimatedCharacter(o)||o.locked)return toast('Select an unlocked character first.');if(recording||window.editorTaskBusy)return;
 if(storyLines(current()).length>=200)return toast('This scene already has 200 dialogue lines.');const line=makeStoryLine('',o.id);line.start=clamp(time,0,current().duration-.1);line.manualStart=line.start;const hadDialogue=Object.hasOwn(current(),'dialogue');(current().dialogue??=[]).push(line);narratorComposerDraft={project,scene:current(),line,hadDialogue};await openOfflineVoice(line);$('offlineVoiceDialog').querySelector('h2').textContent='Voice for '+o.name;$('addOfflineVoice').textContent='Add character voice';$('voiceScriptLength').textContent='Write what '+o.name+' says. This voice belongs to this character.';
}
const controlsBeforeCharacterComposer=renderControls;renderControls=function(){controlsBeforeCharacterComposer();const o=object();if(!isAnimatedCharacter(o))return;const panel=$('controls').querySelector('[data-character-panel="voice"]')||$('controls');const b=storyButton('Create voice for '+o.name,()=>openCharacterComposer(o));b.id='createCharacterVoice';b.disabled=!!o.locked;panel.prepend(b)};
const canvasVoiceBeforeComposer=$('canvasVoice').onclick;$('canvasVoice').onclick=()=>{canvasVoiceBeforeComposer();const panel=$('controls').querySelector('[data-character-panel="voice"]');panel?.scrollIntoView({block:'nearest'})};
render();
